import 'package:flutter/material.dart';
import '../widgets/campo_texto.dart';

class RegistroScreen extends StatefulWidget {
  const RegistroScreen({super.key});

    @override
      State<RegistroScreen> createState() => _RegistroScreenState();
      }

      class _RegistroScreenState extends State<RegistroScreen> {
        final _formKey = GlobalKey<FormState>();
          final _nombreController = TextEditingController();
            final _correoController = TextEditingController();
              final _claveController = TextEditingController();
                final _confirmaController = TextEditingController();
                  bool _acepta = false;
                    bool _cargando = false;
                      bool _mostrarErrorTerminos = false;

                        @override
                          void initState() {
                              super.initState();
                                  // Si cambia la contraseña y ya hay confirmación, se revalida el formulario
                                      _claveController.addListener(() {
                                            if (_confirmaController.text.isNotEmpty) {
                                                    _formKey.currentState?.validate();
                                                          }
                                                              });
                                                                }

                                                                  @override
                                                                    void dispose() {
                                                                        _nombreController.dispose();
                                                                            _correoController.dispose();
                                                                                _claveController.dispose();
                                                                                    _confirmaController.dispose();
                                                                                        super.dispose();
                                                                                          }

                                                                                            String? _validarNombre(String? valor) {
                                                                                                if (valor == null || valor.trim().isEmpty) return 'Escribe tu nombre';
                                                                                                    return null;
                                                                                                      }

                                                                                                        String? _validarCorreo(String? valor) {
                                                                                                            final texto = valor?.trim() ?? '';
                                                                                                                final formato = RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$');
                                                                                                                    if (!formato.hasMatch(texto)) return 'Escribe un correo válido';
                                                                                                                        return null;
                                                                                                                          }

                                                                                                                            String? _validarClave(String? valor) {
                                                                                                                                if (valor == null || valor.length < 8) {
                                                                                                                                      return 'La contraseña debe tener al menos 8 caracteres';
                                                                                                                                          }
                                                                                                                                              return null;
                                                                                                                                                }

                                                                                                                                                  // Validación cruzada: compara con el controlador de la contraseña
                                                                                                                                                    String? _validarConfirmacion(String? valor) {
                                                                                                                                                        if (valor != _claveController.text) {
                                                                                                                                                              return 'Las contraseñas no coinciden';
                                                                                                                                                                  }
                                                                                                                                                                      return null;
                                                                                                                                                                        }

                                                                                                                                                                          Future<void> _registrar() async {
                                                                                                                                                                              final formularioValido = _formKey.currentState!.validate();
                                                                                                                                                                                  setState(() => _mostrarErrorTerminos = !_acepta);
                                                                                                                                                                                      if (!formularioValido || !_acepta) return;

                                                                                                                                                                                          setState(() => _cargando = true);
                                                                                                                                                                                              await Future.delayed(const Duration(seconds: 1));
                                                                                                                                                                                                  if (!mounted) return;
                                                                                                                                                                                                      setState(() => _cargando = false);
                                                                                                                                                                                                          // Regresa al Login devolviendo el correo
                                                                                                                                                                                                              Navigator.pop(context, _correoController.text.trim());
                                                                                                                                                                                                                }

                                                                                                                                                                                                                  @override
                                                                                                                                                                                                                    Widget build(BuildContext context) {
                                                                                                                                                                                                                        return Scaffold(
                                                                                                                                                                                                                              appBar: AppBar(title: const Text('Crear cuenta')),
                                                                                                                                                                                                                                    body: SingleChildScrollView(
                                                                                                                                                                                                                                            padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                                                    child: Form(
                                                                                                                                                                                                                                                              key: _formKey,
                                                                                                                                                                                                                                                                        child: Column(
                                                                                                                                                                                                                                                                                    children: [
                                                                                                                                                                                                                                                                                                  CampoTexto(
                                                                                                                                                                                                                                                                                                                  etiqueta: 'Nombre',
                                                                                                                                                                                                                                                                                                                                  controlador: _nombreController,
                                                                                                                                                                                                                                                                                                                                                  validador: _validarNombre,
                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                              const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                            CampoTexto(
                                                                                                                                                                                                                                                                                                                                                                                                            etiqueta: 'Correo',
                                                                                                                                                                                                                                                                                                                                                                                                                            controlador: _correoController,
                                                                                                                                                                                                                                                                                                                                                                                                                                            validador: _validarCorreo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            teclado: TextInputType.emailAddress,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      CampoTexto(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      etiqueta: 'Contraseña',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      controlador: _claveController,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      validador: _validarClave,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      oculto: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CampoTexto(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                etiqueta: 'Confirmar contraseña',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                controlador: _confirmaController,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                validador: _validarConfirmacion,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                oculto: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CheckboxListTile(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value: _acepta,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChanged: (v) => setState(() => _acepta = v ?? false),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title: const Text('Acepto los términos y condiciones'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            controlAffinity: ListTileControlAffinity.leading,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (_mostrarErrorTerminos && !_acepta)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'Debes aceptar los términos',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style: TextStyle(color: Colors.red),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onPressed: _cargando ? null : _registrar,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: _cargando
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? const SizedBox(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            width: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: CircularProgressIndicator(strokeWidth: 2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : const Text('Registrarme'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }